// MODULE 2 — PARSE & STRUCTURE PRODUCT DATA
// Parse scraped HTML data and extract structured product information

const allProducts = [];

// Process input from all sources
for (const item of $input.all()) {
  const source = item.json;

  // Example structured product extraction
  // In production, use proper HTML parsing (cheerio) or API responses
  if (source.title && source.link) {
    allProducts.push({
      productName: source.title,
      productUrl: source.link,
      productImage: source.image || source.enclosure?.url || '',
      price: source.price || 'Check Price',
      category: source.category || 'General',
      popularityScore: source.traffic || 50,
      source: source.source || 'Google Trends',
      discoveredAt: new Date().toISOString()
    });
  }
}

// Deduplicate by product URL
const seen = new Set();
const uniqueProducts = allProducts.filter(p => {
  const key = p.productUrl;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Sort by popularity score
uniqueProducts.sort((a, b) => b.popularityScore - a.popularityScore);

// Return top 20 products
return uniqueProducts.slice(0, 20).map(p => ({ json: p }));

