// MODULE 3 — FILTER APPROVED PRODUCTS
// Parse AI response and filter only approved products

const aiResponse = $json.choices?.[0]?.message?.content || '{}';
let analysis;

try {
  // Extract JSON from response (handle markdown code blocks)
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(jsonMatch ? jsonMatch[0] : aiResponse);
} catch (e) {
  analysis = { approved: false, reason: 'Failed to parse AI response' };
}

if (!analysis.approved) {
  return []; // Skip non-approved products
}

// Get the original product data from the input chain
const product = $('Parse & Structure Products').item.json;

return [{
  json: {
    ...product,
    aiAnalysis: analysis,
    approvedAt: new Date().toISOString()
  }
}];

