// MODULE 5 — PARSE PIN CONTENT
// Parse AI-generated pin content and merge with product data

const aiResponse = $json.choices?.[0]?.message?.content || '{}';
let pinContent;

try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  pinContent = JSON.parse(jsonMatch ? jsonMatch[0] : aiResponse);
} catch (e) {
  // Fallback content generation
  const product = $('Merge Affiliate Link Data').item.json;
  pinContent = {
    title: `Amazing ${product.category} Find You Need!`,
    description: `Check out this incredible ${product.productName}! Perfect for everyday use. Click the link to get yours today! #${product.category.replace(/\s/g, '')} #AmazonFinds #MustHave`,
    curiosityHook: `This ${product.category} product is going viral!`,
    keywords: [product.category, 'must have', 'trending', 'viral', 'amazon finds'],
    hashtags: ['#AmazonFinds', '#MustHave', '#Trending'],
    boardCategory: product.category,
    suggestedBoards: [`${product.category} Finds`, 'Must-Have Products']
  };
}

// Ensure title is max 70 characters
if (pinContent.title && pinContent.title.length > 70) {
  pinContent.title = pinContent.title.substring(0, 67) + '...';
}

const product = $('Merge Affiliate Link Data').item.json;

return [{
  json: {
    ...product,
    pinContent
  }
}];

// MODULE 6 — IMAGE PROMPT GENERATION
// Generate Stable Diffusion prompts automatically based on product category
// Generates 1 optimized prompt per product to balance quality and API cost

const product = $json;
const category = (product.category || 'general').toLowerCase();
const productName = product.productName || 'product';

// Category-specific prompt enhancements
const categoryPrompts = {
  kitchen: 'modern kitchen setting, marble countertop, warm ambient lighting, cooking utensils in background',
  gadgets: 'sleek tech workspace, minimalist desk setup, LED accent lighting, futuristic feel',
  home: 'cozy living room setting, soft natural light, modern interior design, comfortable atmosphere',
  beauty: 'elegant vanity setting, soft pink lighting, luxurious marble surface, rose petals accent',
  fashion: 'minimalist fashion backdrop, studio lighting, elegant fabric texture, lifestyle photography',
  fitness: 'bright gym setting, energetic atmosphere, clean modern equipment, motivational vibe',
  study: 'organized study desk, warm lamp light, books and stationery, productive atmosphere',
  electronics: 'modern tech setup, ambient blue lighting, clean geometric background, premium feel',
  baby: 'soft pastel nursery, gentle lighting, warm cozy feeling, safe and comfortable',
  default: 'clean minimal studio background, professional product photography, centered composition'
};

// Find best matching category
let categoryPrompt = categoryPrompts.default;
for (const [key, value] of Object.entries(categoryPrompts)) {
  if (category.includes(key)) {
    categoryPrompt = value;
    break;
  }
}

// Generate 1 optimized prompt per product (1024x1536 matches SDXL API dimensions)
const prompt = {
  prompt: `Pinterest marketing pin design, vertical layout 1024x1536, ${productName} centered prominently, ${categoryPrompt}, bright vibrant colors, clean modern design, space for headline text at top, professional marketing aesthetic, high quality product photography, soft studio lighting, 4k detailed`,
  negative: 'blurry, low quality, distorted, watermark, text, words, letters, ugly, deformed, noisy, grainy, dark, cluttered',
  variation: 'optimized'
};

return [{
  json: {
    ...product,
    imagePrompt: prompt.prompt,
    negativePrompt: prompt.negative,
    variation: prompt.variation
  }
}];

// MODULE 7 — PROCESS GENERATED IMAGES
// Extract base64 image data and prepare for Pinterest upload

const response = $json;
const product = $('Generate Image Prompts').item.json;

const artifacts = response.artifacts || [];

if (artifacts.length === 0) {
  // If image generation failed, use product image as fallback
  return [{
    json: {
      ...product,
      imageGenerated: false,
      imageError: 'No image artifacts returned',
      imageBase64: '',
      imageMimeType: 'image/png'
    }
  }];
}

const artifact = artifacts[0];

// Store the base64 image data in JSON for use by Pinterest publish node
// Pinterest API supports image_base64 source type
return [{
  json: {
    ...product,
    imageGenerated: true,
    imageSeed: artifact.seed,
    imageFinishReason: artifact.finishReason,
    imageBase64: artifact.base64,
    imageMimeType: 'image/png'
  }
}];

// MODULE 8 — PIN ASSEMBLY
// Combine title, description, image, and affiliate link into a Pinterest pin object

const product = $json;
const pinContent = product.pinContent || {};
const imageGenerated = product.imageGenerated !== false;

// Determine the target board based on category
const boardMapping = {
  'kitchen': 'Kitchen Gadgets',
  'gadgets': 'Smart Home Tools',
  'study': 'Study Productivity',
  'electronics': 'Tech Finds',
  'home': 'Home Essentials',
  'beauty': 'Beauty Must-Haves',
  'fashion': 'Fashion Finds',
  'fitness': 'Fitness Gear',
  'baby': 'Baby Essentials',
  'default': 'Amazon Finds'
};

const category = (product.category || 'default').toLowerCase();
let boardName = boardMapping.default;
for (const [key, value] of Object.entries(boardMapping)) {
  if (category.includes(key)) {
    boardName = value;
    break;
  }
}

// Assemble the complete pin object
const pin = {
  // Pinterest pin fields
  title: pinContent.title || `Amazing ${product.productName} Find!`,
  description: pinContent.description || `Check out ${product.productName}! ${pinContent.hashtags?.join(' ') || '#AmazonFinds #MustHave #Trending'}`,
  destinationUrl: product.affiliateLink || product.productUrl,
  boardName: boardName,

  // Image data - use generated base64 or fall back to product image URL
  imageBase64: product.imageBase64 || '',
  imageMimeType: product.imageMimeType || 'image/png',
  imageUrl: product.productImage || '',
  imageGenerated: imageGenerated,

  // Metadata for tracking
  productName: product.productName,
  productUrl: product.productUrl,
  affiliateLink: product.affiliateLink,
  earnKaroLinkId: product.earnKaroLinkId,
  category: product.category,
  price: product.price,
  variation: product.variation,

  // Content details
  curiosityHook: pinContent.curiosityHook,
  keywords: pinContent.keywords,
  hashtags: pinContent.hashtags,
  suggestedBoards: pinContent.suggestedBoards,

  // Timestamps
  assembledAt: new Date().toISOString(),
  publishScheduled: new Date().toISOString()
};

return [{ json: pin }];

// MODULE 9 — RATE LIMITING & SPAM PREVENTION
// Ensure safe posting frequency for Pinterest

// Pinterest recommends max 25 pins per day per account
const MAX_PINS_PER_DAY = 25;
const DELAY_BETWEEN_PINS_MS = 300000; // 5 minutes between pins

const pin = $json;
const itemIndex = $itemIndex;

// Add delay metadata
pin.postDelay = itemIndex * DELAY_BETWEEN_PINS_MS;
pin.postOrder = itemIndex + 1;
pin.batchId = `batch-${new Date().toISOString().split('T')[0]}`;

// Check if we've exceeded daily limit
if (itemIndex >= MAX_PINS_PER_DAY) {
  pin.deferred = true;
  pin.deferredReason = `Exceeded daily limit of ${MAX_PINS_PER_DAY} pins`;
  pin.scheduledFor = new Date(Date.now() + 86400000).toISOString(); // Next day
}

return [{ json: pin }];

