// MODULE 9 — HANDLE PUBLISH RESPONSE
// Process Pinterest API response and prepare data for storage

const publishResponse = $json;
const pinData = $('Assemble Pin Object').item.json;

const result = {
  // Pin publish result
  pinId: publishResponse.id || '',
  publishedSuccessfully: !!publishResponse.id,
  pinterestUrl: publishResponse.id ? `https://www.pinterest.com/pin/${publishResponse.id}` : '',

  // Original pin data
  ...pinData,

  // Timestamps
  publishedAt: new Date().toISOString(),

  // Error handling
  publishError: publishResponse.error || null,
  publishErrorMessage: publishResponse.message || null
};

return [{ json: result }];

// MODULE 11 — GENERATE WEEKLY ANALYTICS REPORT

const pins = $input.all().map(item => item.json);

// Calculate metrics
const totalPins = pins.length;
const publishedPins = pins.filter(p => p.published).length;
const failedPins = totalPins - publishedPins;

// Category breakdown
const categoryStats = {};
for (const pin of pins) {
  const cat = pin.category || 'Unknown';
  if (!categoryStats[cat]) {
    categoryStats[cat] = { count: 0, published: 0 };
  }
  categoryStats[cat].count++;
  if (pin.published) categoryStats[cat].published++;
}

// Board breakdown
const boardStats = {};
for (const pin of pins) {
  const board = pin.boardName || 'Unknown';
  if (!boardStats[board]) {
    boardStats[board] = 0;
  }
  boardStats[board]++;
}

const report = {
  reportDate: new Date().toISOString(),
  period: 'Last 7 Days',
  summary: {
    totalPinsGenerated: totalPins,
    publishedSuccessfully: publishedPins,
    failed: failedPins,
    successRate: totalPins > 0 ? ((publishedPins / totalPins) * 100).toFixed(1) + '%' : '0%'
  },
  categoryBreakdown: categoryStats,
  boardBreakdown: boardStats,
  topCategories: Object.entries(categoryStats)
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 5)
    .map(([name, stats]) => ({ name, ...stats }))
};

return [{ json: report }];

// ERROR HANDLER — Global error recovery
// Handles errors from any node in the pipeline

const error = $json;
const errorNode = $execution?.lastNodeExecuted || 'Unknown';

const errorReport = {
  errorAt: new Date().toISOString(),
  node: errorNode,
  message: error.message || error.error || 'Unknown error',
  code: error.code || error.statusCode || 'N/A',
  executionId: $execution?.id || 'N/A',

  // Retry info
  retryable: true,
  maxRetries: 3,
  retryDelay: 60000 // 1 minute
};

return [{ json: errorReport }];
